-- Generated from prisma/schema.prisma; security policies below are deliberate custom SQL.
CREATE TYPE "AccountType" AS ENUM ('CUSTOMER','CLEANER','ADMIN');
CREATE TYPE "AccountState" AS ENUM ('ACTIVE','RESTRICTED','SUSPENDED','INVITED');
CREATE TYPE "OnboardingStatus" AS ENUM ('DRAFT','SUBMITTED','UNDER_REVIEW','NEEDS_CHANGES','REJECTED','APPROVED');
CREATE TYPE "BookingStatus" AS ENUM ('DRAFT','REQUESTED','ACCEPTED','SCHEDULED','IN_PROGRESS','COMPLETED','CONFIRMED','SETTLED','DECLINED','EXPIRED','CANCELLED_BY_CUSTOMER','CANCELLED_BY_CLEANER','CANCELLED_BY_ADMIN','NO_SHOW','DISPUTED');
CREATE TYPE "PaymentStatus" AS ENUM ('PENDING','AUTHORIZED','REQUIRES_ACTION','CAPTURED','RELEASED','REFUNDED','FAILED');
CREATE TYPE "JobStatus" AS ENUM ('QUEUED','RUNNING','SUCCEEDED','RETRY','FAILED');
CREATE TABLE "Account"("id" text PRIMARY KEY,"email" text NOT NULL,"type" "AccountType" NOT NULL,"state" "AccountState" NOT NULL DEFAULT 'ACTIVE',"passwordHash" text,"mfaEnabled" boolean NOT NULL DEFAULT false,"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamp(3) NOT NULL,UNIQUE("email","type"));
CREATE TABLE "Session"("id" text PRIMARY KEY,"accountId" text NOT NULL REFERENCES "Account"("id"),"scope" "AccountType" NOT NULL,"expiresAt" timestamp(3) NOT NULL,"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Customer"("id" text PRIMARY KEY,"accountId" text NOT NULL UNIQUE REFERENCES "Account"("id"),"name" text NOT NULL,"phone" text,"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Cleaner"("id" text PRIMARY KEY,"accountId" text NOT NULL UNIQUE REFERENCES "Account"("id"),"name" text NOT NULL,"bio" text,"hourlyRateCents" integer NOT NULL DEFAULT 3000,"onboarding" "OnboardingStatus" NOT NULL DEFAULT 'DRAFT',"connectPayoutsEnabled" boolean NOT NULL DEFAULT false,"publicPhotoKey" text,"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ServiceArea"("id" text PRIMARY KEY,"cleanerId" text NOT NULL REFERENCES "Cleaner"("id") ON DELETE CASCADE,"postcodePrefix" text NOT NULL,UNIQUE("cleanerId","postcodePrefix"));
CREATE TABLE "Availability"("id" text PRIMARY KEY,"cleanerId" text NOT NULL REFERENCES "Cleaner"("id") ON DELETE CASCADE,"weekday" integer NOT NULL,"startsAt" text NOT NULL,"endsAt" text NOT NULL,"active" boolean NOT NULL DEFAULT true);
CREATE TABLE "Booking"("id" text PRIMARY KEY,"customerId" text NOT NULL REFERENCES "Customer"("id"),"cleanerId" text REFERENCES "Cleaner"("id"),"postcode" text NOT NULL,"durationMinutes" integer NOT NULL,"extras" jsonb NOT NULL,"recurrenceWeeks" integer,"consentId" text,"status" "BookingStatus" NOT NULL DEFAULT 'DRAFT',"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Occurrence"("id" text PRIMARY KEY,"bookingId" text NOT NULL REFERENCES "Booking"("id") ON DELETE CASCADE,"startsAt" timestamp(3) NOT NULL,"timezone" text NOT NULL DEFAULT 'Europe/Berlin',"localStart" text NOT NULL,"status" "BookingStatus" NOT NULL DEFAULT 'REQUESTED',"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamp(3) NOT NULL,UNIQUE("bookingId","localStart"));
CREATE TABLE "LifecycleEvent"("id" text PRIMARY KEY,"occurrenceId" text NOT NULL REFERENCES "Occurrence"("id") ON DELETE CASCADE,"fromStatus" "BookingStatus","toStatus" "BookingStatus" NOT NULL,"actorId" text NOT NULL,"reason" text,"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Consent"("id" text PRIMARY KEY,"customerId" text NOT NULL,"termsVersion" text NOT NULL,"acceptedAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"revokedAt" timestamp(3),"proof" jsonb NOT NULL,"mandateReference" text);
CREATE TABLE "FinancialSnapshot"("id" text PRIMARY KEY,"occurrenceId" text NOT NULL UNIQUE REFERENCES "Occurrence"("id"),"version" integer NOT NULL DEFAULT 1,"currency" text NOT NULL DEFAULT 'EUR',"durationMinutes" integer NOT NULL,"rateCents" integer NOT NULL,"extrasCents" integer NOT NULL,"grossCents" integer NOT NULL,"commissionBps" integer NOT NULL,"commissionCents" integer NOT NULL,"cleanerNetCents" integer NOT NULL,"taxTreatment" text NOT NULL,"ruleVersion" text NOT NULL,"frozenAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Payment"("id" text PRIMARY KEY,"occurrenceId" text NOT NULL UNIQUE REFERENCES "Occurrence"("id"),"provider" text NOT NULL,"providerReference" text UNIQUE,"status" "PaymentStatus" NOT NULL DEFAULT 'PENDING',"authorizedCents" integer NOT NULL DEFAULT 0,"capturedCents" integer NOT NULL DEFAULT 0,"idempotencyKey" text NOT NULL UNIQUE,"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Refund"("id" text PRIMARY KEY,"paymentId" text NOT NULL REFERENCES "Payment"("id"),"amountCents" integer NOT NULL,"reason" text NOT NULL,"providerReference" text,"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Complaint"("id" text PRIMARY KEY,"occurrenceId" text NOT NULL UNIQUE REFERENCES "Occurrence"("id"),"reason" text NOT NULL,"status" text NOT NULL DEFAULT 'OPEN',"openedAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"resolvedAt" timestamp(3),"resolution" text);
CREATE TABLE "Review"("id" text PRIMARY KEY,"occurrenceId" text NOT NULL UNIQUE REFERENCES "Occurrence"("id"),"rating" integer NOT NULL,"body" text,"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Relationship"("id" text PRIMARY KEY,"customerId" text NOT NULL,"cleanerId" text NOT NULL,"recurringCompletedCount" integer NOT NULL DEFAULT 0,"convertedFromOneTime" boolean NOT NULL DEFAULT false,UNIQUE("customerId","cleanerId"));
CREATE TABLE "Document"("id" text PRIMARY KEY,"cleanerId" text NOT NULL REFERENCES "Cleaner"("id") ON DELETE CASCADE,"kind" text NOT NULL,"storageKey" text NOT NULL UNIQUE,"approvedAt" timestamp(3),"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "WebhookEvent"("id" text PRIMARY KEY,"provider" text NOT NULL,"payload" jsonb NOT NULL,"receivedAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"processedAt" timestamp(3));
CREATE TABLE "AuditLog"("id" text PRIMARY KEY,"adminId" text NOT NULL,"action" text NOT NULL,"targetType" text NOT NULL,"targetId" text NOT NULL,"reason" text NOT NULL,"metadata" jsonb,"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AppConfig"("id" text PRIMARY KEY,"key" text NOT NULL,"version" integer NOT NULL,"value" jsonb NOT NULL,"activeAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("key","version"));
CREATE TABLE "Job"("id" text PRIMARY KEY,"kind" text NOT NULL,"dedupeKey" text NOT NULL UNIQUE,"payload" jsonb NOT NULL,"status" "JobStatus" NOT NULL DEFAULT 'QUEUED',"attempts" integer NOT NULL DEFAULT 0,"runAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastError" text);
CREATE INDEX "Booking_customerId_status_idx" ON "Booking"("customerId","status"); CREATE INDEX "Booking_cleanerId_status_idx" ON "Booking"("cleanerId","status"); CREATE INDEX "Occurrence_status_startsAt_idx" ON "Occurrence"("status","startsAt"); CREATE INDEX "Job_status_runAt_idx" ON "Job"("status","runAt");
-- Runtime queries must call set_config through withRls() in the same transaction.
ALTER TABLE "Customer" ENABLE ROW LEVEL SECURITY; ALTER TABLE "Cleaner" ENABLE ROW LEVEL SECURITY; ALTER TABLE "Booking" ENABLE ROW LEVEL SECURITY; ALTER TABLE "Occurrence" ENABLE ROW LEVEL SECURITY; ALTER TABLE "Consent" ENABLE ROW LEVEL SECURITY; ALTER TABLE "Document" ENABLE ROW LEVEL SECURITY; ALTER TABLE "Payment" ENABLE ROW LEVEL SECURITY; ALTER TABLE "FinancialSnapshot" ENABLE ROW LEVEL SECURITY; ALTER TABLE "AuditLog" ENABLE ROW LEVEL SECURITY; ALTER TABLE "WebhookEvent" ENABLE ROW LEVEL SECURITY; ALTER TABLE "Job" ENABLE ROW LEVEL SECURITY;
CREATE POLICY customer_own ON "Customer" USING ("accountId"=current_setting('app.account_id',true));
CREATE POLICY cleaner_own ON "Cleaner" USING ("accountId"=current_setting('app.account_id',true));
CREATE POLICY customer_booking ON "Booking" USING ("customerId" IN (SELECT id FROM "Customer" WHERE "accountId"=current_setting('app.account_id',true)));
CREATE POLICY cleaner_booking ON "Booking" USING ("cleanerId" IN (SELECT id FROM "Cleaner" WHERE "accountId"=current_setting('app.account_id',true)));
CREATE POLICY occurrence_visible ON "Occurrence" USING ("bookingId" IN (SELECT id FROM "Booking"));
CREATE POLICY consent_owner ON "Consent" USING ("customerId" IN (SELECT id FROM "Customer" WHERE "accountId"=current_setting('app.account_id',true)));
CREATE POLICY document_cleaner ON "Document" USING ("cleanerId" IN (SELECT id FROM "Cleaner" WHERE "accountId"=current_setting('app.account_id',true)));
-- No policy intentionally exists for financial, audit, webhook and job tables: they are private system tables. Admin operations run audited SECURITY DEFINER functions in production.
